def remember_cached(self, world, geometry):
    from erc_phase1_solution.exact_world_geometry import _WorldSurface
    if type(geometry) is _WorldSurface and geometry.matches(world):
        _, bounds = geometry.views()
        self._entries[id(world)] = (world, {'min': bounds[0], 'max': bounds[1]})
        self._geometry[id(world)] = (world, geometry)

